from collections import Counter

def transform(grid):
    g=[row[:] for row in grid]
    R,C=len(g),len(g[0])
    pts={(r,c) for r in range(R) for c in range(C) if g[r][c] not in (0,1)}
    objs=[]
    while pts:
        stack=[pts.pop()]; comp=[]
        while stack:
            p=stack.pop();comp.append(p)
            near=[q for q in pts if abs(q[0]-p[0])<=2 and abs(q[1]-p[1])<=2]
            for q in near: pts.remove(q);stack.append(q)
        objs.append(comp)
    for obj in objs:
        colors=Counter(g[r][c] for r,c in obj)
        center=colors.most_common(1)[0][0]
        cr=sum(r for r,c in obj if g[r][c]==center)/colors[center]
        cc=sum(c for r,c in obj if g[r][c]==center)/colors[center]
        others=[p for p in obj if g[p[0]][p[1]]!=center]
        quads={}
        for p in others:
            key=(1 if p[0]>cr else -1,1 if p[1]>cc else -1)
            quads.setdefault(key,[]).append(p)
        for (sr,sc),ps in quads.items():
            color=Counter(g[r][c] for r,c in ps).most_common(1)[0][0]
            origins=[min(ps),max(ps)]
            for r,c in origins:
                r+=sr;c+=2*sc
                while 0<=r<R and 0<=c<C:
                    if g[r][c] in (0,1): g[r][c]=color
                    r+=sr;c+=2*sc
    return g

